    pub fn advances_durable_clock(self) -> bool {
        match self {
            Self::Attempt => false,
            #[cfg(not(feature = "n384-prep"))]
            Self::Node => true,
            #[cfg(feature = "n384-prep")]
            Self::Step => true,
        }
    }
}

